// Qrypt quickstart (Node 20.12+): 1 KiB of quantum entropy -> AES-256-GCM key.
// No dependencies: uses built-in fetch, process.loadEnvFile and node:crypto.
// Put QRYPT_API_KEY=[REDACTED] token> in a .env file next to this script.
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

const API = process.env.QRYPT_BASE_URL ?? "https://api-eus.qrypt.com";

// One friendly message per failure. We never retry automatically.
const HELP = {
  missing: "QRYPT_API_KEY is missing: add it to .env.",
  400: "400: size must be 1-512. It counts KiB, not bytes.",
  401: "401: Authorization header missing, malformed or expired.",
  403: "403: Token invalid OR monthly quota used. Check the token first.",
  429: "429: rate limited. Wait 10 s or more and never loop.",
};

function fail(msg) {
  console.error(msg);
  process.exit(1);
}

// Step 1: read the token from .env. Never print or log it.
try { process.loadEnvFile(".env"); } catch { /* fall through to the check below */ }
const token = process.env.QRYPT_API_KEY;
if (!token) fail(HELP.missing);

// Step 2: fetch 1 KiB of entropy.
let entropyB64;
try {
  const resp = await fetch(`${API}/api/v1/quantum-entropy?size=1`, {
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: "application/json",
      "User-Agent": "qrypt-quickstart/1.0",
      "X-Qrypt-Client": "quickstart-js/1.0",
    },
    signal: AbortSignal.timeout(15_000),
  });
  if (resp.status !== 200) {
    fail(HELP[resp.status] ?? `${resp.status}: Qrypt is busy or erroring. Try again shortly.`);
  }
  entropyB64 = (await resp.json()).random[0];
} catch {
  fail("Network error or non-JSON reply: check proxy/TLS, retry soon.");
}

// Step 3: decode first, then keep 32 bytes as the AES-256 key.
const key = Buffer.from(entropyB64, "base64").subarray(0, 32);
if (key.length !== 32) fail("Unexpected entropy length from Qrypt.");

// Step 4: encrypt and decrypt a sample message with AES-256-GCM.
const nonce = randomBytes(12);
const message = Buffer.from("hello, quantum entropy");
const enc = createCipheriv("aes-256-gcm", key, nonce);
const ciphertext = Buffer.concat([enc.update(message), enc.final()]);
const dec = createDecipheriv("aes-256-gcm", key, nonce).setAuthTag(enc.getAuthTag());
const plaintext = Buffer.concat([dec.update(ciphertext), dec.final()]);
if (!plaintext.equals(message)) fail("AES-256-GCM round trip failed.");

console.log("Success: AES-256-GCM round trip with a Qrypt key (not shown).");

